create extension if not exists pgcrypto;
create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null, type text not null check(type in ('school','nursery','kindergarten')), created_at timestamptz not null default now());
create table public.memberships (organization_id uuid not null references public.organizations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role text not null check(role in ('owner','admin','staff')), primary key(organization_id,user_id));
create table public.branches (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, name text not null);
create table public.guardians (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, user_id uuid references auth.users(id), full_name text not null, phone text);
create table public.children (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, full_name text not null, date_of_birth date, created_at timestamptz not null default now());
create table public.child_guardians (organization_id uuid not null references public.organizations(id) on delete cascade, child_id uuid not null references public.children(id) on delete cascade, guardian_id uuid not null references public.guardians(id) on delete cascade, relationship text not null, primary key(child_id,guardian_id));
create table public.enrollments (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, child_id uuid not null references public.children(id), branch_id uuid references public.branches(id), status text not null default 'pending' check(status in ('pending','approved','rejected','withdrawn')), created_at timestamptz not null default now());
create table public.invoices (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, guardian_id uuid references public.guardians(id), amount_sar numeric(12,2) not null check(amount_sar>=0), status text not null default 'draft' check(status in ('draft','issued','paid','void')), created_at timestamptz not null default now());
create index on public.memberships(user_id);
create index on public.children(organization_id);
create index on public.enrollments(organization_id);
create index on public.invoices(organization_id);
create or replace function public.is_org_member(org uuid) returns boolean language sql stable security definer set search_path = '' as $$ select exists(select 1 from public.memberships m where m.organization_id=org and m.user_id=(select auth.uid())) $$;
revoke all on function public.is_org_member(uuid) from public;
grant execute on function public.is_org_member(uuid) to authenticated;
alter table public.organizations enable row level security;
alter table public.memberships enable row level security;
alter table public.branches enable row level security;
alter table public.guardians enable row level security;
alter table public.children enable row level security;
alter table public.child_guardians enable row level security;
alter table public.enrollments enable row level security;
alter table public.invoices enable row level security;
create policy org_read on public.organizations for select to authenticated using(public.is_org_member(id));
create policy membership_read on public.memberships for select to authenticated using(public.is_org_member(organization_id));
create policy branches_read on public.branches for select to authenticated using(public.is_org_member(organization_id));
create policy guardians_read on public.guardians for select to authenticated using(public.is_org_member(organization_id));
create policy children_read on public.children for select to authenticated using(public.is_org_member(organization_id));
create policy child_guardians_read on public.child_guardians for select to authenticated using(public.is_org_member(organization_id));
create policy enrollments_read on public.enrollments for select to authenticated using(public.is_org_member(organization_id));
create policy invoices_read on public.invoices for select to authenticated using(public.is_org_member(organization_id));
